mapper.select:
SELECT o.id, o.order_no, o.account_id, a.username, a.nickname, o.total_amount, o.status, o.create_time, (SELECT COALESCE(SUM(oi.quantity), 0) FROM order_item oi WHERE oi.order_id = o.id) AS item_count FROM orders o LEFT JOIN account a ON a.id = o.account_id AND a.deleted = 0 WHERE o.deleted = 0
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND (a.username LIKE CONCAT('%', #{username}, '%') OR a.nickname LIKE CONCAT('%', #{username}, '%'))
AND o.status = #{status}
AND o.create_time >= #{dateFrom}
AND o.create_time < #{dateTo}
ORDER BY o.create_time DESC, o.id DESC
